#!/usr/bin/env python3
from pathlib import Path
import hashlib,json,tempfile,subprocess,shutil
C=Path(__file__).resolve().parents[1];P=C/'proof';sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
def diff(old,new,rel):
 r=subprocess.run(['diff','-u','--label','a/'+rel,'--label','b/'+rel,str(old),str(new)],capture_output=True,text=True);assert r.returncode in [0,1];return r.stdout
run=Path(tempfile.mkdtemp(prefix='repair-replay-',dir=C/'.build'));base=run/'base';base.mkdir();orig=json.loads((P/'originals.json').read_text());mains={};parts=[]
for side,key in [('NEON','neon'),('RVV','rvv')]:
 rel='impl/test'+side+'.c';old=P/'original'/('test'+side+'.c');now=C/rel;assert sha(old)==orig['files'][key]['sha256'];mains[key]={'original_sha256':sha(old),'current_sha256':sha(now),'original_source':'proof/original/test'+side+'.c','current_source':rel};part=diff(old,now,rel);mains[key]['patch']='proof/repair-'+key+'.patch';parts.append(part);target=base/rel;target.parent.mkdir(parents=True,exist_ok=True);shutil.copyfile(old,target)
 oldpatch=P/('repair-'+key+'.patch')
 if oldpatch.exists():hist=P/'history/repair';hist.mkdir(exist_ok=True,parents=True);shutil.copyfile(oldpatch,hist/(sha(oldpatch)+'-'+oldpatch.name))
 oldpatch.write_text(part);mains[key]['patch_sha256']=sha(oldpatch)
for name in ['repair.json','repair-draft.json','repair.patch','repair-bundle.patch']:
 old=P/name
 if old.exists():hist=P/'history/repair';hist.mkdir(exist_ok=True,parents=True);shutil.copyfile(old,hist/(sha(old)+'-'+name))
(P/'repair.patch').write_text(''.join(parts));support={str(p.relative_to(C)):sha(p)for p in sorted((C/'shim').glob('*'))if p.suffix in ['.c','.h']};bundle=''.join(parts)
for rel in support:bundle+=diff('/dev/null',C/rel,rel)
patch=P/'repair-bundle.patch';patch.write_text(bundle);cmd=['patch','--batch','--fuzz=0','-p1','-d',str(base),'-i',str(patch)];r=subprocess.run(cmd,capture_output=True,text=True,timeout=60);(run/'patch.log').write_text(r.stdout+r.stderr);assert r.returncode==0,(r.returncode,r.stdout,r.stderr)
expected={'impl/testNEON.c':sha(C/'impl/testNEON.c'),'impl/testRVV.c':sha(C/'impl/testRVV.c'),**support};actual={str(p.relative_to(base)):sha(p)for p in base.rglob('*')if p.is_file()};assert actual==expected,{'extra':set(actual)-set(expected),'missing':set(expected)-set(actual),'changed':[p for p in expected if actual.get(p)!=expected[p]]}
for side,key in [('NEON','neon'),('RVV','rvv')]:
 replay=run/key;replay.mkdir();p=replay/'impl';p.mkdir();shutil.copyfile(P/'original'/('test'+side+'.c'),p/('test'+side+'.c'));cmd2=['patch','--batch','--fuzz=0','-p1','-d',str(replay),'-i',str(P/('repair-'+key+'.patch'))];rr=subprocess.run(cmd2,capture_output=True,text=True,timeout=60);(run/(key+'-patch.log')).write_text(rr.stdout+rr.stderr);assert rr.returncode==0 and sha(p/('test'+side+'.c'))==mains[key]['current_sha256']
receipts={}
for name in ['original-native-counterexample-status.json','native-undefined-status.json','native-address-status.json','rv64-buildability-status.json','neon-front-buildability-status.json','fp-arithmetic-status.json','root-source-pixel-facts-status.json','support-proof-status.json','copy-proof-status.json','nan-helper-proof-status.json','neon3-proof-status.json','read-scalar-proof-status.json','store-half-proof-status.json','assert-proof-status.json']:
 p=P/name;d=json.loads(p.read_text());assert d.get('passed')is True,name;receipts[name]={'sha256':sha(p),'scope':d.get('scope'),'run_directory':d.get('run_directory')}
d={'status':'repaired-candidate, pending complete actual C kernel/public proof and fresh case admission','whole_kernel_verified':False,'original_catalog_sha256':orig['catalog_sha256'],'implementations':mains,'repair_patch':'proof/repair.patch','repair_patch_sha256':sha(P/'repair.patch'),'bundle_patch':'proof/repair-bundle.patch','bundle_patch_sha256':sha(patch),'supporting_source_sha256':support,'zero_fuzz_replay':{'passed':True,'run_directory':str(run),'command':cmd,'log_sha256':sha(run/'patch.log'),'exact_file_inventory_sha256':expected},'counterexample':{'receipt':'proof/original-native-counterexample-status.json','scope':'Actual original NEON and original RVV full C kernels in separately defined ISA emulation, plus independent scalar source-order whole outmap oracle. Original NEON sha was original87a57d56, not a later extracted variant. Finite witness, not physical ISA execution.','witness':'H1,W1,top1,start0,end1,C1,pattern1,alias0,VLpolicy0,cell0; original NEON/oracle7fc00000 vs original RVVc0000000.'},'semantic_repairs':['Mask the actual strided loads; do not dereference inactive/invalid left or right lanes.','Apply second-row upper clamp too.','Explicit canonical NaN propagation through actual checked ordinary helpers.','Odd right absent taps skip FMA entirely by true _mu accumulator-preserving masked FMA; left padding still computes0*weight.','Use local0..3 uint32 lane comparisons plus uint64 global index/address arithmetic; no INT32 dimension cut.','Store row1 before row0 so clipped final row is overwritten by the valid row0, retaining lane0..3 final-channel aliases.'],'compatibility_changes':['NEON three vertical FMAs extracted to4 ordinary pointer-borrow helpers with original per-accumulator operand/lane/order trace.','NEON low/high selection plus2lane store uses2 ordinary checked pointer-borrow helpers; original row/channel write order retained.','RVV scalar-copy classifier avoids pinned QCP syntactic self-comparison issue; exact binary32 copy body checked.','RVV pure mask comparison/load temporaries made explicit for readonly borrowed record views; scalar reads use actual checked reader.'],'domain':{'dimensions':'uint64 values bounded only by explicit valid nonwrapping input/zero/weights/params/output footprints; positive H/W/channels, top0..1,0<=start<end with2*(end-1)+1-top<H. No arbitrary32bit or finite/ordered-float restriction.','read_alias':'Single shared RO map permits complete/partial input, supplied zero-row, packed weights and params aliases; zero row arbitrary fp32 values.','output':'Standard nonoverlapping logical CHW windows with stride gaps and arbitrary initial Some/None outside/written state. Internal clipped last-row and last-channel padded-lane3 aliases retained by actual store order. General overlapping logical CHW windows not claimed.','fp':'All binary32 values incl q/sNaN,Inf,±0,subnormal and unordered bounds. RNE; default-NaN/flush modes/traps disabled, flags unobserved.','rvv':'Fixed VLEN128/e32m1/VLMAX4/XLEN64, all legal VL choices0..4 at spec; active loop positive, inactive data arbitrary.'},'evidence':receipts,'trust_boundary':'Original-instruction32 views source-reviewed-spec, no new Coq axiom; exact ISA spec correspondence and physical SIMD ABI mapping not formally proved, final manual review pending. Ordinary helpers/kernel/loop/memory/public callers require actual typed C VC closure. Finite native and SDK buildability are separate evidence only.','historical_records':'proof/history retains old draft/patch/source, rejected auto32BE/RInt defs, annotation/tool generation failures and pre-mask component evidence.'};(P/'repair.json').write_text(json.dumps(d,indent=2)+'\n');(run/'status.json').write_text(json.dumps({'passed':True,'scope':'Exact source/zero-fuzz repair replay only, no whole-kernel proof credit','repair_json_sha256':sha(P/'repair.json'),'exact_file_inventory_sha256':expected},indent=2)+'\n');print(run,sha(P/'repair.json'))
